class LinkChecker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.refs = []
        self.title = ''
        self.in_title = False
    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        if tag == 'title':
            self.in_title = True
        for attr in ('href', 'src'):
            if attr in d:
                self.refs.append((tag, attr, d[attr]))
    def handle_endtag(self, tag):
        if tag == 'title':
            self.in_title = False
    def handle_data(self, data):
        if self.in_title:
